import argparse

import etl_runtime as rt

# ---- Resolved configuration (from vendor_orders.etlspec.yaml — edit the spec, not this) ----
CONFIG = {
    "name": "vendor_orders",
    "encoding": "utf-8",                      # source.encoding — detected-confirmed
    "delimiter": ",",                         # source.dialect
    "quotechar": '"',                         # source.dialect
    "expected_columns": ["order_id", "cust_name", "amt", "dt", "active", "zip"],
    "output_columns": ["order_id", "customer_name", "amount", "order_date",
                       "is_active", "postal_code"],
    "policies": {
        # Mirrors the spec's policies block (provenance noted per entry).
        "unicode_normalization": "NFC",       # ENC-03 — default
        "strip_control_chars": True,          # ENC-04 — default
        "normalize_unicode_whitespace": True, # ENC-05 — default
        "trim_whitespace": True,              # NUL-02 — default
        "empty_string_is_null": True,         # NUL-01 — explicit
        "null_propagation": "sql",            # NUL-* — default (coercers pass None through)
        "datetime_rendering": "iso8601",      # TYP-05 — default
        "error_disposition": "quarantine",    # ERR-01 — default
        "error_budget": {"percent": 25, "min_rows": 2},  # ERR-02 — explicit
        "duplicate_rows": "keep",             # STR-05 — default (no dedup performed)
        # Per-column null sentinels (NUL-03) — detected-confirmed
        "sentinels": {"dt": ["N/A"]},
    },
}


def transform_row(row, rt_ctx):
    """Map one cleaned input row -> output row. Raise rt.RowError to reject the row.

    `row` values arrive already text-cleaned and null-resolved per policy
    (ENC-03/04/05, NUL-01/02/03 applied and counted by the runtime).
    """
    out = {}
    # order_id <- order_id  [TYP-07: kept as string, uniform 8-digit — detected-confirmed;
    #                        non-nullable target -> NUL-04 check]
    out["order_id"] = rt.not_null(row["order_id"], "order_id")
    # customer_name <- cust_name  [direct rename; non-nullable target -> NUL-04 check]
    out["customer_name"] = rt.not_null(row["cust_name"], "cust_name")
    # amount <- amt  [TYP-01: strip $/commas, (n)=negative — detected-confirmed;
    #                 target decimal scale 2, TYP-08 guards excess precision]
    out["amount"] = rt.to_decimal(row["amt"], "amt", thousands_sep=",",
                                  currency=True, accounting_negative=True, scale=2)
    # order_date <- dt  [TYP-03: MDY — explicit user decision (US-format source system);
    #                    sentinel "N/A" -> null handled by runtime (NUL-03); nullable]
    out["order_date"] = rt.to_date(row["dt"], "dt", formats=["%m/%d/%Y"])
    # is_active <- active  [TYP-06: Y/N vocabulary — detected-confirmed; nullable]
    out["is_active"] = rt.to_bool(row["active"], "active", mapping={"Y": True, "N": False})
    # postal_code <- zip  [TYP-07: string, leading zeros present — detected-confirmed;
    #                      TYP-11: max_length 10, never silently truncate; nullable]
    out["postal_code"] = rt.check_length(row["zip"], "zip", max_length=10)
    return out


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("input")
    p.add_argument("--out-dir", default="./etl_out")
    args = p.parse_args()
    result = rt.run_pipeline(
        input_path=args.input,
        out_dir=args.out_dir,
        config=CONFIG,
        transform_row=transform_row,
    )
    raise SystemExit(result.exit_code)


if __name__ == "__main__":
    main()
